<?php
declare(strict_types=1);

namespace App\Core;

/**
 * File storage on local disk (storage/uploads, outside the web root on cPanel). Keys are generated by the application, never taken from
 * user input; the adapter still refuses any key that could escape its root. Content type is decided by sniffing the bytes, not the
 * client's Content-Type or file name.
 */
final class Storage
{
    private static function root(): string
    {
        $r = rtrim((string) Config::get('storage_dir'), '/\\') . '/uploads';
        if (!is_dir($r)) @mkdir($r, 0750, true);
        return $r;
    }

    private static function resolve(string $key): string
    {
        if (!preg_match('#^[A-Za-z0-9/_.-]{1,200}$#', $key) || str_contains($key, '..') || str_starts_with($key, '/')) throw new \InvalidArgumentException('Invalid storage key');
        return self::root() . '/' . $key;
    }

    /** Write to a temp file and rename: readers never see a half-written upload. */
    public static function put(string $key, string $data): void
    {
        $full = self::resolve($key);
        $dir = dirname($full);
        if (!is_dir($dir) && !@mkdir($dir, 0750, true) && !is_dir($dir)) throw new \RuntimeException('Cannot create storage directory');
        $tmp = $full . '.' . Ids::hex(4) . '.tmp';
        if (file_put_contents($tmp, $data, LOCK_EX) === false) throw new \RuntimeException('Cannot write file');
        @chmod($tmp, 0640);
        if (!rename($tmp, $full)) { @unlink($tmp); throw new \RuntimeException('Cannot store file'); }
    }

    public static function get(string $key): string
    {
        $d = @file_get_contents(self::resolve($key));
        if ($d === false) throw new \RuntimeException('File missing');
        return $d;
    }

    public static function delete(string $key): void
    {
        @unlink(self::resolve($key));
    }

    /** @return array{mime:string,kind:string,ext:string}|null */
    public static function sniff(string $b): ?array
    {
        $n = strlen($b);
        if ($n >= 3 && $b[0] === "\xff" && $b[1] === "\xd8" && $b[2] === "\xff") return ['mime' => 'image/jpeg', 'kind' => 'image', 'ext' => 'jpg'];
        if ($n >= 8 && substr($b, 0, 8) === "\x89PNG\r\n\x1a\n") return ['mime' => 'image/png', 'kind' => 'image', 'ext' => 'png'];
        if ($n >= 12 && substr($b, 0, 4) === 'RIFF' && substr($b, 8, 4) === 'WEBP') return ['mime' => 'image/webp', 'kind' => 'image', 'ext' => 'webp'];
        if ($n >= 5 && substr($b, 0, 5) === '%PDF-') return ['mime' => 'application/pdf', 'kind' => 'document', 'ext' => 'pdf'];
        return null;
    }

    /** Display name only (never used as a path): strip directories, control characters and quotes. */
    public static function safeFileName(?string $raw, string $fallback): string
    {
        $parts = preg_split('#[\\\\/]#', (string) $raw) ?: [''];
        $base = (string) end($parts);
        $clean = trim((string) preg_replace('/[\x00-\x1f\x7f"<>|?*:]/', '', $base));
        $clean = mb_substr($clean, 0, 150);
        return $clean !== '' ? $clean : $fallback;
    }
}
